using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckPoker.Editor {
public static class PokerMobileDealerAuthoring {
 public static void Upgrade(){EditorSceneManager.OpenScene(PokerAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<PokerMatch>();Install(m);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();PokerAuthoring.Validate();}
 public static void Install(PokerMatch m){var drive=m.GetComponent<PokerMobileDealer>();if(drive==null){drive=m.gameObject.AddComponent<PokerMobileDealer>();drive.match=m;drive.vehicle=m.presentation.dealer;drive.hand=m.presentation.dealHand;drive.transit=new Transform[16];var source=m.presentation.seatCards[0].GetComponentInParent<Canvas>().transform.parent;for(int i=0;i<16;i++){var card=UnityEngine.Object.Instantiate(source.gameObject).transform;card.name="Dealer face-down transit card "+i;card.GetComponentInChildren<PokerCardView>(true).Clear(false);foreach(var c in card.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var rb in card.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(rb);drive.transit[i]=card;card.gameObject.SetActive(false);}}
  m.dealerDrive=drive;if(drive.pacingLabel==null){var title=m.menus.pages[0].transform.Find("Title").GetComponent<RectTransform>();title.anchoredPosition=new Vector2(-205,406);title.sizeDelta=new Vector2(900,60);var subtitle=m.menus.pages[0].transform.Find("Subtitle");if(subtitle!=null)subtitle.gameObject.SetActive(false);drive.pacingLabel=SportsUIAuthoring.Button(m.menus.pages[0].transform,"DEALER: CINEMATIC","pokerdealspeed",new Vector2(0,268),new Vector2(520,44)).normalTextObj;}
  if(drive.skipButton==null){var button=SportsUIAuthoring.Button(m.menus.hud.transform,"SKIP DEALING","skipdeal",new Vector2(0,0),new Vector2(310,44));var r=button.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,1);r.pivot=new Vector2(.5f,1);r.anchoredPosition=new Vector2(0,-62);drive.skipButton=button.gameObject;drive.skipButton.SetActive(false);}PokerVenueAuthoring.Install(m);PokerRestaurantDressing.Install(m);PokerTabletopDealerAuthoring.Install(m);EditorUtility.SetDirty(drive);EditorUtility.SetDirty(m);
 }
}
}
